def priority(item: float, bins: np.ndarray) -> np.ndarray:
    priority_scores = np.full_like(bins, np.inf)
    can_fit = bins >= item
    if np.any(can_fit):
        priority_scores[can_fit] = item / (bins[can_fit] - item + 1e-12)
    return priority_scores

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    priority_scores = np.full_like(bins, np.inf)
    can_fit = bins >= item
    if np.any(can_fit):
        priority_scores[can_fit] = - (item / bins[can_fit])
    return priority_scores
